/**
 * Typed field bindings. §4 table.
 *
 * These handle the things every template gets wrong by hand: empty state, aspect
 * ratio, lazy loading, and — for rich text — the XSS posture.
 */

import type { CSSProperties, ReactNode } from "react";

import { useAsset, useField, useMode } from "./context";

/** Split a gallery field's encoded value into URLs.
 *
 *  §14.17: `ProjectContent.values` is a flat Record<string, string|boolean|null>
 *  per section and MUST stay that way — every field type added so far encodes
 *  into a string precisely to avoid touching the persistence layer. Gallery is
 *  newline-separated, matching the existing editor's GalleryField. */
export function parseGallery(value: unknown): string[] {
  if (typeof value !== "string" || value.trim() === "") return [];
  return value
    .split("\n")
    .map((line) => line.trim())
    .filter(Boolean);
}

export function Text({
  field,
  as: Tag = "span",
  className,
  style,
  fallback = "",
}: {
  field: string;
  as?: "span" | "p" | "h1" | "h2" | "h3" | "h4" | "div" | "strong" | "em";
  className?: string;
  style?: CSSProperties;
  fallback?: string;
}) {
  const value = useField<string>(field);
  const text = typeof value === "string" && value !== "" ? value : fallback;
  // A text node, never markup — this is the whole XSS posture in one line.
  return (
    <Tag className={className} style={style}>
      {text}
    </Tag>
  );
}

/**
 * Markdown-lite rich text.
 *
 * Renders to REACT NODES, never `dangerouslySetInnerHTML` — §10.2 rejects that
 * identifier outright in both tiers and calls it non-negotiable, because it is
 * the one thing that would let field values become markup and undo the
 * platform's entire XSS posture. Supporting only bold/italic/line breaks keeps
 * that promise cheap to hold.
 */
export function RichText({
  field,
  className,
  style,
}: {
  field: string;
  className?: string;
  style?: CSSProperties;
}) {
  const value = useField<string>(field) ?? "";

  const blocks = value.split(/\n{2,}/).filter((b) => b.trim() !== "");

  return (
    <div className={className} style={style}>
      {blocks.map((block, blockIndex) => (
        <p key={blockIndex}>{renderInline(block)}</p>
      ))}
    </div>
  );
}

/** `**bold**`, `*italic*`, and single newlines. Everything else is literal. */
function renderInline(text: string): ReactNode[] {
  const nodes: ReactNode[] = [];
  const pattern = /(\*\*[^*]+\*\*|\*[^*]+\*|\n)/g;
  let lastIndex = 0;
  let match: RegExpExecArray | null;
  let key = 0;

  while ((match = pattern.exec(text)) !== null) {
    if (match.index > lastIndex) {
      nodes.push(text.slice(lastIndex, match.index));
    }
    const token = match[0];
    if (token === "\n") {
      nodes.push(<br key={key++} />);
    } else if (token.startsWith("**")) {
      nodes.push(<strong key={key++}>{token.slice(2, -2)}</strong>);
    } else {
      nodes.push(<em key={key++}>{token.slice(1, -1)}</em>);
    }
    lastIndex = match.index + token.length;
  }
  if (lastIndex < text.length) {
    nodes.push(text.slice(lastIndex));
  }
  return nodes;
}

export function Img({
  field,
  alt = "",
  className,
  style,
  fit = "cover",
}: {
  field: string;
  alt?: string;
  className?: string;
  style?: CSSProperties;
  fit?: "cover" | "contain";
}) {
  const src = useField<string>(field);
  if (!src) {
    // Explicit empty state: an <img> with no src renders as a broken-image icon,
    // which looks like a bug in a preview screenshot.
    return (
      <div
        data-cp-empty={field}
        className={className}
        style={{
          width: "100%",
          height: "100%",
          background: "var(--cp-surface, rgba(0,0,0,0.06))",
          ...style,
        }}
      />
    );
  }
  return (
    <img
      src={src}
      alt={alt}
      loading="lazy"
      decoding="async"
      className={className}
      style={{ width: "100%", height: "100%", objectFit: fit, ...style }}
    />
  );
}

export function Gallery({
  field,
  className,
  style,
  renderItem,
}: {
  field: string;
  className?: string;
  style?: CSSProperties;
  renderItem?: (src: string, index: number) => ReactNode;
}) {
  const raw = useField<string>(field);
  const items = parseGallery(raw);
  if (items.length === 0) return null;

  return (
    <div className={className} style={style}>
      {items.map((src, index) =>
        renderItem ? (
          <div key={`${src}-${index}`}>{renderItem(src, index)}</div>
        ) : (
          <img
            key={`${src}-${index}`}
            src={src}
            alt=""
            loading="lazy"
            decoding="async"
            style={{ width: "100%", display: "block" }}
          />
        ),
      )}
    </div>
  );
}

/**
 * Audio. Autoplay is deliberately suppressed in "edit" mode — a track
 * restarting on every keystroke makes the editor unusable, and browsers block
 * unprompted autoplay anyway.
 */
export function Audio({
  field,
  loop = true,
  className,
}: {
  field: string;
  loop?: boolean;
  className?: string;
}) {
  const src = useField<string>(field);
  const mode = useMode();
  if (!src) return null;
  return (
    <audio
      src={src}
      loop={loop}
      controls
      autoPlay={mode === "published"}
      className={className}
    />
  );
}

export function Video({
  field,
  poster,
  className,
  style,
}: {
  field: string;
  poster?: string;
  className?: string;
  style?: CSSProperties;
}) {
  const src = useField<string>(field);
  const mode = useMode();
  if (!src) return null;
  return (
    <video
      src={src}
      poster={poster}
      playsInline
      muted
      loop
      controls
      autoPlay={mode !== "edit"}
      className={className}
      style={{ width: "100%", ...style }}
    />
  );
}

/** Resolve a packaged asset ("assets/bg.webp") to its absolute CDN URL. */
export function Asset({
  path,
  children,
}: {
  path: string;
  children: (url: string) => ReactNode;
}) {
  const assets = useAsset();
  return <>{children(assets(path))}</>;
}
