/**
 * defineTemplate — the single entry point of a template package. §4, §5 step 5.
 *
 * It does two jobs at once, and the fact that they share ONE object is the point:
 *
 *   1. At BUILD time the CLI imports the module and reads `config` to emit
 *      manifest.json. The manifest is therefore DERIVED from the same literal
 *      the runtime uses — an author cannot declare a field in the manifest that
 *      the component does not read, or read one it did not declare, because
 *      there is only one declaration.
 *   2. At RUNTIME the platform calls `Template(props)`, which mounts the runtime
 *      context and renders `config.render()`.
 *
 * §2.1(a) says "the manifest is the contract, not the code". This is how that
 * contract stays honest without a second source of truth to keep in sync.
 */

import { TemplateRuntime } from "./context";
import type {
  TemplateConfig,
  TemplateModule,
  TemplateProps,
} from "./types";

export type DefinedTemplate = TemplateModule & {
  /** Read by the CLI to emit manifest.json. Not used at runtime. */
  config: TemplateConfig;
};

export function defineTemplate(config: TemplateConfig): DefinedTemplate {
  function Template(props: TemplateProps) {
    return (
      <TemplateRuntime
        value={{
          content: props.content ?? {},
          design: props.design ?? { theme: {}, overrides: {}, canvas: {} },
          mode: props.mode ?? "preview",
          assets: props.assets ?? ((path: string) => path),
        }}
      >
        {config.render() as never}
      </TemplateRuntime>
    );
  }

  return {
    Template,
    config,
    // Replaced by the CLI at build time with the real sha256 of the emitted
    // manifest.json (§3.4). The placeholder is what an unbuilt/hand-assembled
    // package carries, and the upload validator rejects it — that single check
    // is what keeps the manifest and the code honest about each other.
    manifestHash: "",
  };
}
